{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Document with nested enums and strings",
  "type": "object",
  "properties": {
    "meta": {
      "type": "object",
      "properties": {
        "version": {
          "type": "string"
        },
        "locale": {
          "type": "string",
          "enum": ["en-US", "en-GB", "fr-FR", "zh-CN"]
        }
      },
      "required": ["version", "locale"]
    },
    "payload": {
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "enum": ["Order", "Invoice", "Refund"]
        },
        "status": {
          "type": "string",
          "enum": ["pending", "complete", "failed"]
        },
        "items": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "id": {
                "type": "string"
              },
              "note": {
                "type": "string"
              },
              "category": {
                "type": "string",
                "enum": ["standard", "fragile", "oversize"]
              }
            },
            "required": ["id", "category"]
          }
        }
      },
      "required": ["type", "status"]
    }
  },
  "required": ["meta", "payload"],
  "additionalProperties": false
}
